import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.HashMap;import java.util.Map;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;int n = Integer.parseInt(line1.trim());String line2 = br.readLine();if (line2 == null) return;StringTokenizer st = new StringTokenizer(line2);Map<Integer, Long> counts = new HashMap<>();for (int i = 0; i < n; i++) {int val = Integer.parseInt(st.nextToken());counts.put(val, counts.getOrDefault(val, 0L) + 1);}long totalPairs = 0;for (long count : counts.values()) {if (count > 1) {totalPairs += (count * (count - 1)) / 2;}}System.out.println(totalPairs);}}